import dlt
from pyspark.sql import functions as F

@dlt.table(name="bronze_orders", comment="Raw orders ingested via Auto Loader")
def bronze_orders():
    return (spark.readStream
        .format("cloudFiles")
        .option("cloudFiles.format", "json")
        .option("cloudFiles.schemaLocation", "/mnt/dlt/schema/orders")
        .load("s3://datalake/raw/orders/"))

@dlt.table(name="silver_orders", comment="Cleaned, validated orders")
@dlt.expect_or_drop("positive_amount", "amount > 0")
@dlt.expect_or_fail("valid_order_id", "order_id IS NOT NULL")
def silver_orders():
    return (dlt.read_stream("bronze_orders")
        .withColumn("amount", F.col("amount").cast("double"))
        .withColumn("event_ts", F.to_timestamp("event_ts"))
        .select("order_id", "customer_id", "amount", "event_ts"))

@dlt.table(name="gold_revenue_per_customer", comment="Total revenue per customer")
def gold_revenue_per_customer():
    return (dlt.read("silver_orders")
        .groupBy("customer_id")
        .agg(F.sum("amount").alias("total_revenue"),
             F.count("*").alias("order_count")))

