-- (a) Inspect history to find the good version
DESCRIBE HISTORY accounts;

-- (b) Query the table as of the good version (say version 41)
SELECT * FROM accounts VERSION AS OF 41;
-- or by timestamp
SELECT * FROM accounts TIMESTAMP AS OF ''2026-06-19T23:00:00'';

-- (c) Compare row counts between current and good version
SELECT
  (SELECT count(*) FROM accounts)                AS current_count,
  (SELECT count(*) FROM accounts VERSION AS OF 41) AS good_count;

-- (d) Restore the table to the good version (new commit, reversible)
RESTORE TABLE accounts TO VERSION AS OF 41;

-- (a) Compact small files (optionally scope to recent partitions)
OPTIMIZE events
WHERE event_date >= ''2026-06-01'';

-- (b) Compact AND cluster by the high-cardinality filter column
OPTIMIZE events
WHERE event_date >= ''2026-06-01''
ZORDER BY (device_id);

-- (c) Enable auto compaction + optimized writes for future writes
ALTER TABLE events SET TBLPROPERTIES (
  ''delta.autoOptimize.optimizeWrite'' = ''true'',
  ''delta.autoOptimize.autoCompact''  = ''true''
);

-- Pivot quarters into columns
SELECT * FROM (
  SELECT region, quarter, revenue FROM sales
)
PIVOT (
  SUM(revenue)
  FOR quarter IN (''Q1'' AS Q1, ''Q2'' AS Q2, ''Q3'' AS Q3, ''Q4'' AS Q4)
);

-- Reverse: unpivot the wide table back to long form
SELECT region, quarter, revenue
FROM wide_sales
UNPIVOT (
  revenue FOR quarter IN (Q1, Q2, Q3, Q4)
);

-- 1. Delete the requested users (MERGE-based delete on the id set)
MERGE INTO user_events AS t
USING erasure_requests AS r
ON t.user_id = r.user_id
WHEN MATCHED THEN DELETE;

-- 2. Shorten retention so the removed files become eligible for purge
ALTER TABLE user_events
SET TBLPROPERTIES (delta.deletedFileRetentionDuration = ''interval 0 hours'');

-- 3. Physically purge unreferenced data files (disables the 7-day guard)
SET spark.databricks.delta.retentionDurationCheck.enabled = false;
VACUUM user_events RETAIN 0 HOURS;

-- 1. Convert Parquet to Delta in place (declare partition cols if partitioned)
CONVERT TO DELTA parquet.`/mnt/lake/sales_parquet/`
PARTITIONED BY (sale_year INT);

-- Register a table name over the location (optional but convenient)
CREATE TABLE sales USING DELTA LOCATION ''/mnt/lake/sales_parquet/'';

-- 2. Add the audit column (metadata-only)
ALTER TABLE sales ADD COLUMN ingested_at TIMESTAMP;

-- 3. Backfill existing rows
UPDATE sales
SET ingested_at = current_timestamp()
WHERE ingested_at IS NULL;

